{
  "application": "ppt-generation",
  "case_id": "case-paper-vapo-rl",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 9,
    "audience": "ML researchers and RL practitioners working on LLM reasoning",
    "tone": "technical, data-forward, analytical"
  },
  "brief": {
    "title": "VAPO: Value-Model-Based RL Achieves 60.4 on AIME 2024, Surpassing DAPO by 10+ Points",
    "one_liner": "VAPO introduces a value-model-based reinforcement learning framework that overcomes key challenges in long chain-of-thought reasoning, achieving state-of-the-art math reasoning performance with superior training stability and efficiency.",
    "goal": "Understand VAPO's architectural innovations (Length-adaptive GAE, value pretraining, decoupled GAE), how each component contributes to its 60.4 AIME score, and why value-model-based RL can outperform value-model-free methods for complex reasoning tasks."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "VAPO: Value-Model-Based RL for Advanced Reasoning — 60.4 on AIME 2024",
      "objective": "Cover slide with paper title, authors (ByteDance Seed), key result (60.4 AIME 2024), and base model (Qwen2.5-32B)."
    },
    {
      "id": "motivation-value-model",
      "title": "Why Value Models? Finer Credit Assignment for Long Chain-of-Thought Reasoning",
      "objective": "Explain the motivation: value-model-free methods (GRPO, DAPO) assign trajectory-level advantage uniformly, while value models enable token-level credit assignment critical for multi-step reasoning. Use a conceptual diagram or bullet comparison of value-free vs value-based approaches."
    },
    {
      "id": "three-core-challenges",
      "title": "Three Challenges Plaguing Value-Model-Based RL in Long-CoT Tasks",
      "objective": "Present the three key challenges: (1) value model bias from long trajectories and bootstrapping, (2) heterogeneous sequence lengths with different bias-variance tradeoffs, (3) reward signal sparsity exacerbated by long CoT. Use a three-column layout or icons."
    },
    {
      "id": "vapo-framework-overview",
      "title": "VAPO Framework: Integrated Solutions for Value-Model-Based Reasoning RL",
      "objective": "Overview of VAPO's key components: Value-Pretraining, Decoupled-GAE, Length-adaptive GAE, Clip-Higher, Token-level Loss, Positive Example LM Loss, and Group-Sampling. Show as a system architecture or component diagram mapping each technique to the challenge it addresses."
    },
    {
      "id": "length-adaptive-gae",
      "title": "Length-Adaptive GAE: Dynamic λ Adjustment for Variable Response Lengths",
      "objective": "Deep dive into the novel Length-adaptive GAE technique that dynamically adjusts the λ parameter based on response length: short responses use lower λ (lower variance) while long responses use higher λ (lower bias), optimizing the bias-variance tradeoff across heterogeneous sequence lengths. Use a conceptual illustration comparing short vs long response λ behavior."
    },
    {
      "id": "aime-score-comparison",
      "title": "VAPO Scores 60 on AIME 2024 — 10+ Points Above DAPO and DeepSeek-R1-Zero",
      "objective": "Present the main results table comparing Vanilla PPO (5), DeepSeek-R1-Zero-Qwen-32B (47), DAPO (50), and VAPO (60). Use a bar chart or highlighted table. Reference figure_2.jpg for the training curve showing VAPO consistently outperforming DAPO throughout training."
    },
    {
      "id": "training-efficiency-curves",
      "title": "VAPO Reaches SOTA in 5K Steps — Half the Training Budget of DAPO",
      "objective": "Show the training curve (figure_2.jpg) comparing VAPO vs DAPO accuracy over training steps, and the response length curve (figure_3.jpg) showing VAPO generates longer reasoning chains. Emphasize training efficiency and stability."
    },
    {
      "id": "ablation-study-results",
      "title": "Ablation: Every Component Matters — Value-Pretraining Alone Adds 49 Points",
      "objective": "Present the ablation table showing the contribution of each component. Highlight that removing Value-Pretraining drops score from 60 to 11, removing Decoupled-GAE drops to 33, and removing Length-adaptive GAE drops to 45. Use a waterfall chart or annotated table."
    },
    {
      "id": "takeaways-implications",
      "title": "Key Takeaways: Value-Model-Based RL Is Back — With the Right Engineering",
      "objective": "Summarize 4-5 key findings: (1) value-model-based methods can surpass value-free when challenges are addressed, (2) Length-adaptive GAE is critical for heterogeneous lengths, (3) value pretraining is the single most important component, (4) VAPO is stable with no training crashes across multiple runs, (5) implications for future reasoning model development."
    }
  ]
}

