<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>VAPO: Value-Model-Based RL for Advanced Reasoning</title>

    <!-- Electric Studio-inspired: Manrope for precision and authority -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Manrope:wght@300;400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap" rel="stylesheet">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES — VAPO THEME
           Electric Studio inspired: dark base, sharp blue/white contrast,
           data-forward with amber accent for results emphasis
           =========================================== */
        :root {
            --bg-deep:      #07090e;
            --bg-panel:     #0d1017;
            --bg-card:      #131924;
            --bg-card-alt:  #0f1520;
            --border:       rgba(255,255,255,0.08);
            --border-accent:rgba(55,135,255,0.4);

            --text-primary:   #f0f4ff;
            --text-secondary: #8896b0;
            --text-muted:     #4a5568;

            --accent-blue:    #3787ff;
            --accent-blue-2:  #1f5fd4;
            --accent-amber:   #f5a623;
            --accent-green:   #3ecf8e;
            --accent-red:     #ef4444;
            --accent-cyan:    #22d3ee;

            /* VAPO brand color — distinctive gold-amber */
            --vapo-gold:      #f5a623;
            --dapo-blue:      #3787ff;
            --baseline-gray:  #4a5568;

            /* Typography */
            --font-display: 'Manrope', sans-serif;
            --font-mono:    'DM Mono', monospace;

            /* Clamp scales — from viewport-base.css overrides */
            --title-size:    clamp(1.6rem, 4.5vw, 4.2rem);
            --h2-size:       clamp(1.2rem, 2.8vw, 2.2rem);
            --h3-size:       clamp(0.95rem, 1.8vw, 1.4rem);
            --body-size:     clamp(0.75rem, 1.3vw, 1rem);
            --small-size:    clamp(0.65rem, 0.9vw, 0.8rem);
            --mono-size:     clamp(0.65rem, 1.1vw, 0.875rem);
            --label-size:    clamp(0.55rem, 0.8vw, 0.72rem);

            --slide-padding: clamp(1.5rem, 4vw, 4.5rem);
            --content-gap:   clamp(0.6rem, 1.5vw, 1.8rem);
            --element-gap:   clamp(0.3rem, 0.8vw, 0.8rem);

            --ease-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --ease-back: cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        /* ===========================================
           VIEWPORT BASE — MANDATORY (from viewport-base.css)
           =========================================== */
        *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

        html, body {
            height: 100%;
            overflow-x: hidden;
            font-family: var(--font-display);
            background: var(--bg-deep);
            color: var(--text-primary);
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            background: var(--bg-deep);
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        .grid {
            display: grid;
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap:   clamp(0.4rem, 1.2vw, 1rem);
                --title-size:    clamp(1.3rem, 4vw, 2.8rem);
                --h2-size:       clamp(1rem, 2.5vw, 1.8rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap:   clamp(0.3rem, 0.9vw, 0.75rem);
                --title-size:    clamp(1.1rem, 3.5vw, 2rem);
                --body-size:     clamp(0.65rem, 1vw, 0.875rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size:    clamp(0.95rem, 3vw, 1.5rem);
                --h2-size:       clamp(0.85rem, 2.2vw, 1.2rem);
                --body-size:     clamp(0.6rem, 0.9vw, 0.8rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           GLOBAL TYPOGRAPHY
           =========================================== */
        h1 {
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.1;
            letter-spacing: -0.02em;
        }
        h2 {
            font-size: var(--h2-size);
            font-weight: 700;
            line-height: 1.2;
            letter-spacing: -0.01em;
        }
        h3 {
            font-size: var(--h3-size);
            font-weight: 600;
            line-height: 1.3;
        }
        p, li {
            font-size: var(--body-size);
            line-height: 1.55;
            color: var(--text-secondary);
        }
        strong { color: var(--text-primary); font-weight: 600; }
        .mono { font-family: var(--font-mono); font-size: var(--mono-size); }

        /* ===========================================
           SHARED SLIDE COMPONENTS
           =========================================== */

        /* Slide header with accent bar */
        .slide-header {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.6rem, 1.5vw, 1.2rem);
            margin-bottom: var(--content-gap);
        }
        .slide-num {
            font-family: var(--font-mono);
            font-size: var(--label-size);
            color: var(--accent-blue);
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-top: 0.35em;
            white-space: nowrap;
        }

        /* Top accent line */
        .accent-bar {
            position: absolute;
            top: 0; left: 0; right: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-blue) 0%, var(--accent-cyan) 100%);
        }

        /* Background grid pattern */
        .grid-bg {
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.018) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.018) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
        }

        /* Corner glow decorations */
        .glow-corner {
            position: absolute;
            border-radius: 50%;
            filter: blur(80px);
            pointer-events: none;
            opacity: 0.15;
        }
        .glow-tl {
            width: clamp(200px, 30vw, 400px);
            height: clamp(200px, 30vw, 400px);
            top: calc(-1 * clamp(100px, 15vw, 200px));
            left: calc(-1 * clamp(100px, 15vw, 200px));
            background: var(--accent-blue);
        }
        .glow-br {
            width: clamp(150px, 25vw, 350px);
            height: clamp(150px, 25vw, 350px);
            bottom: calc(-1 * clamp(80px, 12vw, 180px));
            right: calc(-1 * clamp(80px, 12vw, 180px));
            background: var(--accent-cyan);
        }

        /* Tags / badges */
        .tag {
            display: inline-flex;
            align-items: center;
            gap: 0.3em;
            padding: 0.25em 0.7em;
            border-radius: 4px;
            font-size: var(--small-size);
            font-weight: 600;
            letter-spacing: 0.05em;
            text-transform: uppercase;
            background: rgba(55,135,255,0.15);
            color: var(--accent-blue);
            border: 1px solid rgba(55,135,255,0.3);
        }
        .tag.amber {
            background: rgba(245,166,35,0.15);
            color: var(--accent-amber);
            border-color: rgba(245,166,35,0.3);
        }
        .tag.green {
            background: rgba(62,207,142,0.12);
            color: var(--accent-green);
            border-color: rgba(62,207,142,0.3);
        }
        .tag.red {
            background: rgba(239,68,68,0.12);
            color: var(--accent-red);
            border-color: rgba(239,68,68,0.3);
        }

        /* Stat callout box */
        .stat-box {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.8rem, 2vw, 1.5rem);
            display: flex;
            flex-direction: column;
            gap: 0.2em;
        }
        .stat-number {
            font-size: clamp(1.8rem, 5vw, 4.5rem);
            font-weight: 800;
            line-height: 1;
            color: var(--vapo-gold);
            letter-spacing: -0.03em;
        }
        .stat-label {
            font-size: var(--small-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            font-weight: 500;
        }

        /* ===========================================
           REVEAL ANIMATIONS
           Triggered by .visible class via Intersection Observer
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.55s var(--ease-expo),
                        transform 0.55s var(--ease-expo);
        }
        .slide.visible .reveal { opacity: 1; transform: translateY(0); }
        .slide.visible .reveal:nth-child(1)  { transition-delay: 0.05s; }
        .slide.visible .reveal:nth-child(2)  { transition-delay: 0.12s; }
        .slide.visible .reveal:nth-child(3)  { transition-delay: 0.19s; }
        .slide.visible .reveal:nth-child(4)  { transition-delay: 0.26s; }
        .slide.visible .reveal:nth-child(5)  { transition-delay: 0.33s; }
        .slide.visible .reveal:nth-child(6)  { transition-delay: 0.40s; }
        .slide.visible .reveal:nth-child(7)  { transition-delay: 0.47s; }
        .slide.visible .reveal:nth-child(8)  { transition-delay: 0.54s; }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.93);
            transition: opacity 0.6s var(--ease-expo), transform 0.6s var(--ease-expo);
        }
        .slide.visible .reveal-scale { opacity: 1; transform: scale(1); }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0; left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-blue), var(--accent-cyan));
            width: 0%;
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* ===========================================
           NAV DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.8rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 0.8vh, 0.7rem);
            z-index: 100;
        }
        .nav-dot {
            width: 6px; height: 6px;
            border-radius: 50%;
            background: var(--text-muted);
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
            padding: 0;
        }
        .nav-dot.active {
            background: var(--accent-blue);
            transform: scale(1.5);
        }

        /* ===========================================
           SLIDE 1: TITLE SLIDE
           =========================================== */
        .slide-title {
            background: var(--bg-deep);
        }
        .slide-title .title-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1.5rem, 4vw, 4rem);
            align-items: center;
            height: 100%;
            padding: var(--slide-padding);
        }
        .slide-title .left-col {}
        .slide-title .right-col {
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
            align-items: flex-end;
        }
        .title-eyebrow {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            letter-spacing: 0.15em;
            text-transform: uppercase;
            color: var(--accent-blue);
            margin-bottom: clamp(0.4rem, 1vw, 0.9rem);
        }
        .title-main {
            font-size: clamp(2rem, 5.5vw, 5rem);
            font-weight: 800;
            line-height: 1.05;
            letter-spacing: -0.025em;
            color: var(--text-primary);
        }
        .title-main .vapo-highlight {
            color: var(--vapo-gold);
        }
        .title-sub {
            font-size: clamp(0.8rem, 1.6vw, 1.15rem);
            color: var(--text-secondary);
            max-width: 52ch;
            line-height: 1.5;
            margin-top: clamp(0.5rem, 1.2vw, 1rem);
        }
        .title-score-card {
            background: linear-gradient(135deg, rgba(245,166,35,0.12) 0%, rgba(245,166,35,0.05) 100%);
            border: 1px solid rgba(245,166,35,0.35);
            border-radius: 12px;
            padding: clamp(1rem, 2.5vw, 2rem) clamp(1.2rem, 3vw, 2.5rem);
            text-align: center;
            width: 100%;
            max-width: clamp(180px, 22vw, 280px);
        }
        .score-number {
            font-size: clamp(2.5rem, 6vw, 5.5rem);
            font-weight: 800;
            color: var(--vapo-gold);
            line-height: 1;
            letter-spacing: -0.03em;
        }
        .score-bench {
            font-size: var(--small-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-top: 0.3em;
        }
        .title-meta-row {
            display: flex;
            gap: 0.5rem;
            flex-wrap: wrap;
            justify-content: flex-end;
        }
        .title-divider {
            width: 100%;
            height: 1px;
            background: var(--border);
            margin: clamp(0.5rem, 1vw, 1rem) 0;
        }
        .title-attribution {
            font-size: var(--small-size);
            color: var(--text-muted);
            text-align: right;
        }
        @media (max-width: 700px) {
            .slide-title .title-layout { grid-template-columns: 1fr; }
            .slide-title .right-col { align-items: flex-start; }
            .title-meta-row { justify-content: flex-start; }
            .title-attribution { text-align: left; }
        }

        /* ===========================================
           SLIDE 2: MOTIVATION
           =========================================== */
        .motivation-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.8rem, 2vw, 1.8rem);
            margin-top: var(--content-gap);
        }
        .method-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.8rem, 2vw, 1.4rem);
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }
        .method-card.vapo-method {
            border-color: rgba(245,166,35,0.4);
            background: linear-gradient(145deg, rgba(245,166,35,0.06), var(--bg-card));
        }
        .method-card-title {
            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--text-primary);
        }
        .method-card.vapo-method .method-card-title { color: var(--vapo-gold); }
        .method-card-sub {
            font-size: var(--small-size);
            color: var(--text-muted);
            font-family: var(--font-mono);
            text-transform: uppercase;
            letter-spacing: 0.08em;
        }
        .method-props {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 0.3em;
        }
        .method-props li {
            font-size: var(--body-size);
            color: var(--text-secondary);
            display: flex;
            gap: 0.5em;
            align-items: flex-start;
        }
        .method-props li::before {
            content: '—';
            color: var(--text-muted);
            flex-shrink: 0;
        }
        .method-card.vapo-method .method-props li::before { color: var(--vapo-gold); }
        @media (max-width: 700px) {
            .motivation-grid { grid-template-columns: 1fr; }
        }

        /* ===========================================
           SLIDE 3: THREE CHALLENGES
           =========================================== */
        .challenges-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.6rem, 1.5vw, 1.2rem);
            margin-top: var(--content-gap);
        }
        .challenge-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.8rem, 2vw, 1.4rem);
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
            position: relative;
            overflow: hidden;
        }
        .challenge-card::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0;
            height: 3px;
        }
        .challenge-card:nth-child(1)::before { background: var(--accent-red); }
        .challenge-card:nth-child(2)::before { background: var(--accent-amber); }
        .challenge-card:nth-child(3)::before { background: var(--accent-cyan); }
        .challenge-num {
            font-family: var(--font-mono);
            font-size: clamp(1.8rem, 4vw, 3.5rem);
            font-weight: 500;
            line-height: 1;
            opacity: 0.15;
            letter-spacing: -0.02em;
        }
        .challenge-card:nth-child(1) .challenge-num { color: var(--accent-red); opacity: 0.3; }
        .challenge-card:nth-child(2) .challenge-num { color: var(--accent-amber); opacity: 0.3; }
        .challenge-card:nth-child(3) .challenge-num { color: var(--accent-cyan); opacity: 0.3; }
        .challenge-title {
            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--text-primary);
            line-height: 1.2;
        }
        .challenge-desc {
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }
        @media (max-width: 700px) {
            .challenges-grid { grid-template-columns: 1fr; }
        }

        /* ===========================================
           SLIDE 4: VAPO FRAMEWORK
           =========================================== */
        .framework-layout {
            display: grid;
            grid-template-columns: 1fr 2fr;
            gap: clamp(1rem, 2.5vw, 2.5rem);
            align-items: start;
            margin-top: var(--content-gap);
            max-height: min(70vh, 550px);
            overflow: hidden;
        }
        .challenge-col {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vw, 0.8rem);
        }
        .challenge-pill {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.4rem, 1vw, 0.7rem) clamp(0.6rem, 1.2vw, 1rem);
            font-size: var(--small-size);
            font-weight: 600;
            letter-spacing: 0.03em;
            display: flex;
            align-items: center;
            gap: 0.5em;
        }
        .challenge-pill .dot {
            width: 6px; height: 6px;
            border-radius: 50%;
            flex-shrink: 0;
        }
        .cp-bias .dot   { background: var(--accent-red); }
        .cp-length .dot { background: var(--accent-amber); }
        .cp-sparse .dot { background: var(--accent-cyan); }
        .cp-bias   { color: var(--accent-red); border-color: rgba(239,68,68,0.25); }
        .cp-length { color: var(--accent-amber); border-color: rgba(245,166,35,0.25); }
        .cp-sparse { color: var(--accent-cyan); border-color: rgba(34,211,238,0.25); }
        .col-header {
            font-size: var(--label-size);
            font-family: var(--font-mono);
            text-transform: uppercase;
            letter-spacing: 0.12em;
            color: var(--text-muted);
            margin-bottom: 0.3em;
        }
        .solutions-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.4rem, 1vw, 0.7rem);
        }
        .solution-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vw, 0.9rem);
            display: flex;
            flex-direction: column;
            gap: 0.3em;
        }
        .solution-name {
            font-size: var(--small-size);
            font-weight: 700;
            color: var(--text-primary);
        }
        .solution-desc {
            font-size: clamp(0.58rem, 0.9vw, 0.74rem);
            color: var(--text-muted);
            line-height: 1.4;
        }
        .solution-tag {
            display: inline-flex;
            align-items: center;
            gap: 0.25em;
            width: fit-content;
            padding: 0.12em 0.45em;
            border-radius: 3px;
            font-size: clamp(0.5rem, 0.75vw, 0.62rem);
            font-weight: 600;
            letter-spacing: 0.06em;
            text-transform: uppercase;
            margin-top: auto;
        }
        .st-bias   { background: rgba(239,68,68,0.12); color: var(--accent-red); }
        .st-length { background: rgba(245,166,35,0.12); color: var(--accent-amber); }
        .st-sparse { background: rgba(34,211,238,0.1); color: var(--accent-cyan); }
        .st-multi  { background: rgba(55,135,255,0.1); color: var(--accent-blue); }
        .solution-card.novel {
            border-color: rgba(245,166,35,0.35);
            background: linear-gradient(145deg, rgba(245,166,35,0.05), var(--bg-card));
        }
        @media (max-width: 700px) {
            .framework-layout { grid-template-columns: 1fr; }
            .solutions-grid { grid-template-columns: 1fr; }
        }

        /* ===========================================
           SLIDE 5: LENGTH-ADAPTIVE GAE
           =========================================== */
        .gae-layout {
            display: grid;
            grid-template-columns: 1.1fr 1fr;
            gap: clamp(1rem, 2.5vw, 2.5rem);
            align-items: start;
            margin-top: var(--content-gap);
            overflow: hidden;
        }
        .gae-concept {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vw, 1rem);
        }
        .gae-bullets {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 0.8vw, 0.7rem);
        }
        .gae-bullets li {
            font-size: var(--body-size);
            color: var(--text-secondary);
            display: flex;
            gap: 0.6em;
            align-items: flex-start;
            padding-left: 0;
        }
        .gae-bullets li .bullet-icon {
            flex-shrink: 0;
            width: 1.5em; height: 1.5em;
            border-radius: 4px;
            display: flex; align-items: center; justify-content: center;
            font-size: 0.9em;
            margin-top: 0.1em;
        }
        .gae-diagram {
            display: flex;
            flex-direction: column;
            gap: clamp(0.6rem, 1.2vw, 1rem);
        }
        .lambda-row {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.6rem, 1.5vw, 1.1rem);
            display: flex;
            align-items: center;
            gap: clamp(0.6rem, 1.5vw, 1.2rem);
        }
        .lambda-row.short { border-color: rgba(55,135,255,0.3); }
        .lambda-row.long  { border-color: rgba(245,166,35,0.3); }
        .lambda-icon {
            font-size: clamp(1.2rem, 2.5vw, 2rem);
            flex-shrink: 0;
        }
        .lambda-content { flex: 1; }
        .lambda-title {
            font-size: var(--body-size);
            font-weight: 700;
            color: var(--text-primary);
        }
        .lambda-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.2em;
        }
        .lambda-badge {
            padding: 0.3em 0.7em;
            border-radius: 6px;
            font-family: var(--font-mono);
            font-size: var(--small-size);
            font-weight: 600;
            flex-shrink: 0;
        }
        .lambda-row.short .lambda-badge {
            background: rgba(55,135,255,0.15);
            color: var(--accent-blue);
        }
        .lambda-row.long .lambda-badge {
            background: rgba(245,166,35,0.15);
            color: var(--vapo-gold);
        }
        .gae-insight {
            background: linear-gradient(135deg, rgba(245,166,35,0.08), rgba(245,166,35,0.03));
            border: 1px solid rgba(245,166,35,0.25);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vw, 0.9rem);
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }
        .gae-insight strong { color: var(--vapo-gold); }
        @media (max-width: 700px) {
            .gae-layout { grid-template-columns: 1fr; }
        }

        /* ===========================================
           SLIDE 6: MAIN RESULTS — BAR CHART
           =========================================== */
        .results-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 2.5vw, 2.5rem);
            align-items: start;
            margin-top: var(--content-gap);
            overflow: hidden;
        }
        .bar-chart-wrap {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.8rem, 2vw, 1.5rem);
        }
        .chart-title {
            font-size: var(--small-size);
            font-family: var(--font-mono);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--text-muted);
            margin-bottom: clamp(0.6rem, 1.2vw, 1rem);
        }
        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.45rem, 0.9vw, 0.8rem);
        }
        .bar-row {
            display: grid;
            grid-template-columns: clamp(120px, 18vw, 200px) 1fr clamp(28px, 3vw, 40px);
            align-items: center;
            gap: clamp(0.4rem, 0.8vw, 0.7rem);
        }
        .bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: right;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .bar-track {
            height: clamp(20px, 3vh, 32px);
            background: rgba(255,255,255,0.04);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }
        .bar-fill {
            height: 100%;
            border-radius: 4px;
            position: absolute;
            left: 0; top: 0;
            transition: width 1s var(--ease-expo);
            width: 0%;
        }
        .slide.visible .bar-fill { width: var(--bar-w); }
        .bar-fill.gray    { background: linear-gradient(90deg, #2d3748, #3d4a5e); }
        .bar-fill.blue    { background: linear-gradient(90deg, var(--accent-blue-2), var(--accent-blue)); }
        .bar-fill.blue-lt { background: linear-gradient(90deg, #2a5cb8, #3787ff); }
        .bar-fill.vapo    { background: linear-gradient(90deg, #d4891e, var(--vapo-gold)); }
        .bar-value {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-primary);
        }
        .bar-value.vapo-val { color: var(--vapo-gold); }

        .results-stats {
            display: flex;
            flex-direction: column;
            gap: clamp(0.6rem, 1.2vw, 1rem);
        }
        .delta-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.7rem, 1.5vw, 1.2rem);
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.2vw, 1rem);
        }
        .delta-num {
            font-size: clamp(1.5rem, 3.5vw, 3rem);
            font-weight: 800;
            color: var(--accent-green);
            line-height: 1;
            letter-spacing: -0.02em;
            flex-shrink: 0;
        }
        .delta-desc {
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }
        .delta-desc strong { color: var(--text-primary); }
        .result-note {
            font-size: var(--small-size);
            color: var(--text-muted);
            line-height: 1.5;
            font-style: italic;
        }
        @media (max-width: 700px) {
            .results-layout { grid-template-columns: 1fr; }
        }

        /* ===========================================
           SLIDE 7: TRAINING CURVES
           =========================================== */
        .curves-layout {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vw, 1rem);
            margin-top: var(--content-gap);
            overflow: hidden;
        }
        .curves-images {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.6rem, 1.5vw, 1.2rem);
        }
        .curve-box {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }
        .curve-box img {
            width: 100%;
            max-height: min(35vh, 280px);
            object-fit: contain;
            padding: clamp(0.3rem, 0.8vw, 0.6rem);
        }
        .curve-caption {
            padding: clamp(0.4rem, 0.8vw, 0.6rem) clamp(0.6rem, 1.2vw, 0.9rem);
            border-top: 1px solid var(--border);
            font-size: var(--small-size);
            color: var(--text-muted);
        }
        .efficiency-row {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.5rem, 1vw, 0.8rem);
        }
        .eff-stat {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vw, 0.9rem);
            text-align: center;
        }
        .eff-num {
            font-size: clamp(1.1rem, 2.5vw, 2rem);
            font-weight: 800;
            color: var(--accent-green);
            line-height: 1;
            letter-spacing: -0.02em;
        }
        .eff-label {
            font-size: var(--small-size);
            color: var(--text-muted);
            margin-top: 0.2em;
        }
        @media (max-width: 700px) {
            .curves-images { grid-template-columns: 1fr; }
            .efficiency-row { grid-template-columns: 1fr; }
        }

        /* ===========================================
           SLIDE 8: ABLATION STUDY — WATERFALL TABLE
           =========================================== */
        .ablation-layout {
            display: grid;
            grid-template-columns: 1.5fr 1fr;
            gap: clamp(1rem, 2.5vw, 2.5rem);
            align-items: start;
            margin-top: var(--content-gap);
            overflow: hidden;
        }
        .ablation-table {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            overflow: hidden;
        }
        .ablation-table table {
            width: 100%;
            border-collapse: collapse;
        }
        .ablation-table thead tr {
            background: rgba(255,255,255,0.04);
        }
        .ablation-table th, .ablation-table td {
            padding: clamp(0.35rem, 0.8vw, 0.65rem) clamp(0.6rem, 1.2vw, 1rem);
            text-align: left;
            font-size: var(--small-size);
        }
        .ablation-table th {
            font-family: var(--font-mono);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            color: var(--text-muted);
            font-weight: 500;
            border-bottom: 1px solid var(--border);
        }
        .ablation-table td { color: var(--text-secondary); }
        .ablation-table td.score-td {
            font-family: var(--font-mono);
            font-weight: 600;
            text-align: right;
        }
        .ablation-table td.delta-td {
            font-family: var(--font-mono);
            font-size: clamp(0.58rem, 0.85vw, 0.72rem);
            text-align: right;
            color: var(--accent-red);
            font-weight: 600;
        }
        .ablation-table tr.row-vapo td {
            color: var(--vapo-gold);
            font-weight: 700;
            background: rgba(245,166,35,0.05);
        }
        .ablation-table tr.row-vapo td.score-td { color: var(--vapo-gold); }
        .ablation-table tr:not(:last-child) td { border-bottom: 1px solid rgba(255,255,255,0.04); }
        .ablation-table tr.row-critical td { background: rgba(239,68,68,0.05); }
        .ablation-table tr.row-critical td.score-td { color: var(--accent-red); }
        .critical-badge {
            display: inline-flex;
            align-items: center;
            padding: 0.1em 0.4em;
            border-radius: 3px;
            font-size: clamp(0.48rem, 0.7vw, 0.58rem);
            background: rgba(239,68,68,0.15);
            color: var(--accent-red);
            font-weight: 600;
            margin-left: 0.4em;
            vertical-align: middle;
            font-family: var(--font-mono);
            letter-spacing: 0.05em;
        }

        .ablation-insights {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1vw, 0.8rem);
        }
        .insight-item {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vw, 0.9rem);
            display: flex;
            gap: 0.6em;
            align-items: flex-start;
        }
        .insight-item.critical { border-color: rgba(239,68,68,0.35); background: rgba(239,68,68,0.04); }
        .insight-item.moderate { border-color: rgba(245,166,35,0.35); background: rgba(245,166,35,0.04); }
        .insight-item.minor    { border-color: rgba(62,207,142,0.25); background: rgba(62,207,142,0.03); }
        .insight-delta {
            font-family: var(--font-mono);
